-- Group-selected, per-instance analytical capacity. Existing017 and035 evidence
-- remains immutable; this dedicated evaluator issues only new036 records.
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='finops_group_capacity') THEN CREATE ROLE finops_group_capacity NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;END IF;END $$;

CREATE TABLE fleet_native_capacity_requests (
 tenant_id text NOT NULL,id text NOT NULL,workload_id text NOT NULL,creator_id text NOT NULL,
 old_proposal_id text NOT NULL,candidate_proposal_id text NOT NULL,safety_profile_id text NOT NULL,safety_profile_version bigint NOT NULL,
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,old_proposal_id) REFERENCES fleet_configuration_proposals(tenant_id,id),
 FOREIGN KEY(tenant_id,candidate_proposal_id) REFERENCES fleet_configuration_proposals(tenant_id,id),
 FOREIGN KEY(tenant_id,safety_profile_id) REFERENCES workload_safety_profiles(tenant_id,id),
 CHECK(old_proposal_id<>candidate_proposal_id),CHECK(octet_length(raw_document)<=32768)
);
CREATE TABLE fleet_native_capacity_members (
 tenant_id text NOT NULL,id text NOT NULL,request_id text NOT NULL,instance_id text NOT NULL,
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),input_snapshot_hash text NOT NULL CHECK(input_snapshot_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,request_id,instance_id),
 FOREIGN KEY(tenant_id,request_id) REFERENCES fleet_native_capacity_requests(tenant_id,id),
 CHECK(instance_id~'^i-([a-f0-9]{8}|[a-f0-9]{17})$'),CHECK(octet_length(raw_document)<=1048576)
);
CREATE TABLE fleet_native_capacity_scopes (
 tenant_id text NOT NULL,request_id text NOT NULL,content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),
 input_snapshot_hash text NOT NULL CHECK(input_snapshot_hash~'^[a-f0-9]{64}$'),document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,request_id),FOREIGN KEY(tenant_id,request_id) REFERENCES fleet_native_capacity_requests(tenant_id,id),CHECK(octet_length(raw_document)<=131072)
);
CREATE TABLE fleet_native_capacity_batches (
 tenant_id text NOT NULL,id text NOT NULL,request_id text NOT NULL,
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),input_snapshot_hash text NOT NULL CHECK(input_snapshot_hash~'^[a-f0-9]{64}$'),
 document jsonb NOT NULL,raw_document bytea NOT NULL,
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,request_id),
 FOREIGN KEY(tenant_id,request_id) REFERENCES fleet_native_capacity_requests(tenant_id,id),CHECK(octet_length(raw_document)<=262144)
);
CREATE INDEX fleet_native_capacity_page ON fleet_native_capacity_requests(tenant_id,workload_id,id);
CREATE INDEX fleet_native_capacity_member_page ON fleet_native_capacity_members(tenant_id,request_id,id);
DO $$ DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['fleet_native_capacity_requests','fleet_native_capacity_scopes','fleet_native_capacity_members','fleet_native_capacity_batches'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tab);
 EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK(tenant_id=current_setting(''app.tenant_id'',true))',tab);
 EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION public.deny_evidence_mutation()',tab||'_immutable',tab);
 END LOOP;END $$;
GRANT SELECT ON fleet_native_capacity_requests,fleet_native_capacity_scopes,fleet_native_capacity_members,fleet_native_capacity_batches TO finops_api,finops_group_capacity;
GRANT INSERT ON fleet_native_capacity_requests TO finops_api;
GRANT INSERT ON fleet_native_capacity_scopes,fleet_native_capacity_members,fleet_native_capacity_batches TO finops_group_capacity;
GRANT SELECT ON entities,workload_safety_profiles,source_registrations,source_checkpoints,source_receipts,source_revisions,telemetry_connections,telemetry_source_revisions,telemetry_source_revocations,telemetry_receipts TO finops_group_capacity;
GRANT EXECUTE ON FUNCTION fleet_native_selection_current(text,text,text),fleet_native_current_pin_ids(text,jsonb),fleet_history_json_hash(jsonb),fleet_history_json_text(jsonb) TO finops_group_capacity;
-- Identical immutable IDs/profile request closure; no financial request or
-- financial queue row is created by the capacity route.
CREATE TRIGGER fleet_native_capacity_request_guard BEFORE INSERT ON fleet_native_capacity_requests FOR EACH ROW EXECUTE FUNCTION public.guard_fleet_native_assessment_request();

CREATE FUNCTION guard_fleet_capacity_scope() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE req public.fleet_native_capacity_requests%ROWTYPE;binding jsonb;profile public.workload_safety_profiles%ROWTYPE;pin jsonb;r public.source_receipts%ROWTYPE;rev public.source_revisions%ROWTYPE;old_members jsonb;ids jsonb;current_ids text[];pins text[];candidate_membership jsonb;side jsonb;membership_pins jsonb;claimed_membership_pins jsonb;BEGIN
 IF current_user<>'finops_group_capacity' THEN RAISE EXCEPTION 'fleet capacity scope requires dedicated evaluator';END IF;
 NEW.writer_role:=current_user;NEW.created_at:=clock_timestamp();
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.tenant_id||':dependency-graph',0));
 SELECT * INTO req FROM public.fleet_native_capacity_requests WHERE tenant_id=NEW.tenant_id AND id=NEW.request_id;
 binding:=public.fleet_native_selection_current(NEW.tenant_id,req.old_proposal_id,req.candidate_proposal_id);
 SELECT * INTO profile FROM public.workload_safety_profiles WHERE tenant_id=NEW.tenant_id AND workload_id=req.workload_id ORDER BY version DESC LIMIT 1;
 IF req.id IS NULL OR binding IS NULL OR req.document->'selection'->'groups'->'binding' IS DISTINCT FROM binding OR req.safety_profile_id IS DISTINCT FROM profile.id OR req.safety_profile_version IS DISTINCT FROM profile.version OR NEW.document->>'schema_version' IS DISTINCT FROM '1' OR NEW.document->>'request_id' IS DISTINCT FROM NEW.request_id OR NEW.document->'scope'->'selection' IS DISTINCT FROM req.document->'selection' OR NEW.document->'execution_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'verified_saving' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'scope'->>'snapshot_sha256' IS DISTINCT FROM public.fleet_history_json_hash(jsonb_set(NEW.document,'{scope,snapshot_sha256}','""'::jsonb)) OR encode(sha256(NEW.raw_document),'hex') IS DISTINCT FROM NEW.content_hash OR convert_from(NEW.raw_document,'UTF8')::jsonb IS DISTINCT FROM NEW.document THEN RAISE EXCEPTION 'fleet capacity immutable scope binding differs';END IF;
 IF jsonb_typeof(NEW.document->'scope'->'observed_at') IS DISTINCT FROM 'string' OR (NEW.document->'scope'->>'observed_at')::timestamptz<clock_timestamp()-interval '5 minutes' OR (NEW.document->'scope'->>'observed_at')::timestamptz>clock_timestamp()+interval '5 seconds' OR jsonb_typeof(NEW.document->'scope'->'current_member_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'scope'->'current_member_ids')>256 OR jsonb_typeof(NEW.document->'source_pins') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'source_pins')>4 OR jsonb_typeof(NEW.document->'reason_codes') IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) k WHERE k<>ALL(ARRAY['schema_version','request_id','scope','candidate_template','source_pins','reason_codes','execution_authorized','verified_saving'])) OR jsonb_path_exists(NEW.document,'$.**.samples') OR jsonb_path_exists(NEW.document,'$.**.points') THEN RAISE EXCEPTION 'fleet capacity scope shape invalid';END IF;
 SELECT coalesce(array_agg(s.id ORDER BY s.id),ARRAY[]::text[]) INTO current_ids FROM public.source_receipts s WHERE s.tenant_id=NEW.tenant_id AND s.id=ANY(public.fleet_native_current_pin_ids(NEW.tenant_id,binding)) AND s.kind IN('AWS_FLEET_MEMBERSHIP','AWS_FLEET_LAUNCH_TEMPLATES');
 SELECT coalesce(array_agg(value->>'receipt_id' ORDER BY value->>'receipt_id'),ARRAY[]::text[]) INTO pins FROM jsonb_array_elements(NEW.document->'source_pins');
 IF current_ids IS DISTINCT FROM pins OR cardinality(pins)<>(SELECT count(DISTINCT id) FROM unnest(pins) id) THEN RAISE EXCEPTION 'fleet capacity current point pins differ';END IF;
 FOR pin IN SELECT value FROM jsonb_array_elements(NEW.document->'source_pins') LOOP
  SELECT * INTO r FROM public.source_receipts WHERE tenant_id=NEW.tenant_id AND id=pin->>'receipt_id';SELECT * INTO rev FROM public.source_revisions WHERE tenant_id=NEW.tenant_id AND id=pin->>'revision_id';
  IF coalesce(pin->>'raw_sha256','')!~'^[a-f0-9]{64}$' OR coalesce(pin->>'receipt_sha256','')!~'^[a-f0-9]{64}$' OR coalesce(pin->>'receipt_version_id','') IN('','null') OR coalesce(pin->>'revision_version_id','') IN('','null') OR r.document->'raw_object'->>'bucket' IS DISTINCT FROM rev.document->'raw_object'->>'bucket' OR r.document->'raw_object'->>'key' IS DISTINCT FROM rev.document->'raw_object'->>'key' OR r.document->>'config_hash' IS DISTINCT FROM rev.document->>'config_hash' OR r.document->'registration_version' IS DISTINCT FROM rev.document->'registration_version' THEN RAISE EXCEPTION 'fleet capacity native revision object differs';END IF;
  IF r.id IS NULL OR rev.id IS NULL OR r.writer_role<>'finops_ingester' OR rev.writer_role<>'finops_ingester' OR r.revision_id IS DISTINCT FROM rev.id OR r.source_id IS DISTINCT FROM rev.source_id OR r.document->'raw_object'->>'body_sha256' IS DISTINCT FROM pin->>'raw_sha256' OR rev.document->'raw_object'->>'body_sha256' IS DISTINCT FROM pin->>'raw_sha256' OR r.document->'raw_object'->>'version_id' IS DISTINCT FROM pin->>'receipt_version_id' OR rev.document->'raw_object'->>'version_id' IS DISTINCT FROM pin->>'revision_version_id' OR public.fleet_history_json_hash(r.document||jsonb_build_object('writer_role',r.writer_role,'created_at',r.created_at)) IS DISTINCT FROM pin->>'receipt_sha256' OR NOT EXISTS(SELECT 1 FROM jsonb_each(binding) side WHERE side.value->>'source_id'=r.source_id AND side.value->>'source_config_sha256'=r.document->>'config_hash' AND side.value->'source_registration_version'=r.document->'registration_version') OR jsonb_typeof(r.document->'collected_at') IS DISTINCT FROM 'string' OR (r.document->>'collected_at')::timestamptz<clock_timestamp()-interval '5 minutes' OR (r.document->>'collected_at')::timestamptz>clock_timestamp()+interval '5 seconds' THEN RAISE EXCEPTION 'fleet capacity issued point pin differs';END IF;
  IF r.kind='AWS_FLEET_MEMBERSHIP' THEN
   SELECT value INTO side FROM jsonb_each(binding) WHERE value->'registration'->>'id'=r.document->>'history_registration_id';
   IF side IS NULL OR r.document->'history_registration_version' IS DISTINCT FROM side->'registration'->'version' OR r.document->>'history_registration_hash' IS DISTINCT FROM side->'registration'->>'sha256' OR r.document->'binding' IS DISTINCT FROM jsonb_build_object('tenant_id',NEW.tenant_id,'workload_id',req.workload_id,'provider','AWS','account_id',side->'target'->>'account_id','region',side->'target'->>'region') OR jsonb_array_length(r.document->'groups')<>1 OR r.document->'groups'->0->>'arn' IS DISTINCT FROM side->'target'->>'asg_arn' THEN RAISE EXCEPTION 'fleet capacity native group point differs';END IF;
   IF r.document->>'history_registration_id'=binding->'old'->'registration'->>'id' THEN SELECT coalesce(jsonb_agg(value->>'instance_id' ORDER BY value->>'instance_id'),'[]') INTO old_members FROM jsonb_array_elements(r.document->'groups'->0->'members');END IF;
   IF r.document->>'history_registration_id'=binding->'candidate'->'registration'->>'id' THEN candidate_membership:=r.document->'groups'->0;END IF;
  END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(p.value ORDER BY p.value->>'receipt_id'),'[]') INTO membership_pins FROM jsonb_array_elements(NEW.document->'source_pins') p JOIN public.source_receipts s ON s.tenant_id=NEW.tenant_id AND s.id=p.value->>'receipt_id' AND s.kind='AWS_FLEET_MEMBERSHIP';
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'receipt_id'),'[]') INTO claimed_membership_pins FROM jsonb_array_elements(NEW.document->'scope'->'membership_pins');
 IF membership_pins IS DISTINCT FROM claimed_membership_pins THEN RAISE EXCEPTION 'fleet capacity membership pin subset differs';END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY value),'[]') INTO ids FROM jsonb_array_elements_text(NEW.document->'scope'->'current_member_ids');
 IF (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(ids))<>jsonb_array_length(ids) THEN RAISE EXCEPTION 'fleet capacity member point contains duplicates';END IF;
 IF NEW.document->'scope'->>'population_status'='OBSERVED_POINT' THEN
  IF old_members IS NULL OR ids IS DISTINCT FROM old_members THEN RAISE EXCEPTION 'fleet capacity complete observed roster differs';END IF;
 ELSIF NEW.document->'scope'->>'population_status'='UNAVAILABLE' THEN
  IF old_members IS NOT NULL OR ids<>'[]'::jsonb OR jsonb_array_length(NEW.document->'reason_codes')=0 THEN RAISE EXCEPTION 'unknown population cannot replace an observed point';END IF;
 ELSE RAISE EXCEPTION 'fleet capacity population classification invalid';END IF;
 IF NEW.document->'candidate_template' IS DISTINCT FROM 'null'::jsonb THEN
  IF jsonb_typeof(NEW.document->'candidate_template'->'version') IS DISTINCT FROM 'string' OR coalesce(NEW.document->'candidate_template'->>'version','')!~'^[1-9][0-9]{0,19}$' OR coalesce(NEW.document->'candidate_template'->>'instance_type','')='' OR coalesce(NEW.document->'candidate_template'->>'image_id','')='' OR NEW.document->'candidate_template'->'source_pin' IS DISTINCT FROM (SELECT value FROM jsonb_array_elements(NEW.document->'source_pins') WHERE value->>'receipt_id'=NEW.document->'candidate_template'->'source_pin'->>'receipt_id') THEN RAISE EXCEPTION 'fleet capacity candidate exact pin invalid';END IF;
  IF candidate_membership IS NULL OR NEW.document->'candidate_template'->>'id' IS DISTINCT FROM candidate_membership->'launch_template'->>'id' OR NEW.document->'candidate_template'->>'version' IS DISTINCT FROM candidate_membership->'launch_template'->>'version' OR NEW.document->'candidate_template'->>'definition_sha256' !~ '^[a-f0-9]{64}$' OR NOT EXISTS(SELECT 1 FROM public.source_receipts s WHERE s.tenant_id=NEW.tenant_id AND s.id=NEW.document->'candidate_template'->'source_pin'->>'receipt_id' AND s.kind='AWS_FLEET_LAUNCH_TEMPLATES' AND s.id=ANY(pins)) THEN RAISE EXCEPTION 'fleet capacity selected native candidate template differs';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.source_receipts s CROSS JOIN LATERAL jsonb_array_elements(s.document->'templates') t WHERE s.tenant_id=NEW.tenant_id AND s.id=NEW.document->'candidate_template'->'source_pin'->>'receipt_id' AND t->>'id'=NEW.document->'candidate_template'->>'id' AND t->>'version'=NEW.document->'candidate_template'->>'version' AND t->'data'->>'instance_type'=NEW.document->'candidate_template'->>'instance_type' AND t->'data'->>'image_id'=NEW.document->'candidate_template'->>'image_id' AND t->'data'->'instance_requirements'='false'::jsonb) THEN RAISE EXCEPTION 'fleet capacity concrete candidate type or image differs';END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER fleet_native_capacity_scope_guard BEFORE INSERT ON fleet_native_capacity_scopes FOR EACH ROW EXECUTE FUNCTION public.guard_fleet_capacity_scope();

CREATE FUNCTION guard_fleet_capacity_member() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE req public.fleet_native_capacity_requests%ROWTYPE;issued public.fleet_native_capacity_scopes%ROWTYPE;binding jsonb;resource jsonb;rv bigint;hw public.source_receipts%ROWTYPE;rev public.source_revisions%ROWTYPE;cfg public.telemetry_connections%ROWTYPE;tr public.telemetry_source_revisions%ROWTYPE;ref jsonb;receipt public.telemetry_receipts%ROWTYPE;native_pin jsonb;current_point_ids text[];issued_point_ids text[];BEGIN
 IF current_user<>'finops_group_capacity' THEN RAISE EXCEPTION 'fleet capacity member requires dedicated evaluator';END IF;
 NEW.writer_role:=current_user;NEW.created_at:=clock_timestamp();
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.tenant_id||':dependency-graph',0));
 SELECT * INTO req FROM public.fleet_native_capacity_requests WHERE tenant_id=NEW.tenant_id AND id=NEW.request_id;
 SELECT * INTO issued FROM public.fleet_native_capacity_scopes WHERE tenant_id=NEW.tenant_id AND request_id=NEW.request_id;
 IF req.id IS NULL OR issued.request_id IS NULL OR EXISTS(SELECT 1 FROM public.fleet_native_capacity_batches b WHERE b.tenant_id=NEW.tenant_id AND b.request_id=NEW.request_id) OR NEW.document->>'schema_version' IS DISTINCT FROM '1' OR NEW.document->>'id' IS DISTINCT FROM NEW.id OR NEW.document->>'batch_id' IS DISTINCT FROM NEW.request_id OR NEW.document->>'instance_id' IS DISTINCT FROM NEW.instance_id OR NEW.document->'scope' IS DISTINCT FROM issued.document->'scope' OR NOT (issued.document->'scope'->'current_member_ids' ? NEW.instance_id) OR NEW.document->'group_capacity_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'completed_business_work_preserved' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'execution_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'estimated_saving' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'verified_saving' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'change_plan_id' IS DISTINCT FROM 'null'::jsonb OR encode(sha256(NEW.raw_document),'hex') IS DISTINCT FROM NEW.content_hash OR convert_from(NEW.raw_document,'UTF8')::jsonb IS DISTINCT FROM NEW.document THEN RAISE EXCEPTION 'fleet capacity member scope or no-authority seal differs';END IF;
 IF jsonb_typeof(NEW.document->'observed_at') IS DISTINCT FROM 'string' OR (NEW.document->>'observed_at')::timestamptz<clock_timestamp()-interval '2 minutes' OR (NEW.document->>'observed_at')::timestamptz>clock_timestamp()+interval '5 seconds' OR coalesce(NEW.document->>'status','') NOT IN('BLOCKED','UNAVAILABLE') OR coalesce(NEW.document->>'demand_meaning','') NOT IN('REQUEST_THROUGHPUT_PROXY','UNAVAILABLE') OR jsonb_typeof(NEW.document->'model_requested') IS DISTINCT FROM 'boolean' OR jsonb_typeof(NEW.document->'model_evaluated') IS DISTINCT FROM 'boolean' OR jsonb_typeof(NEW.document->'reason_codes') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'reason_codes')=0 OR coalesce(NEW.document->>'input_hash','')!~'^[a-f0-9]{64}$' OR jsonb_path_exists(NEW.document,'$.**.points') OR jsonb_path_exists(NEW.document,'$.**.samples') OR jsonb_path_exists(NEW.document,'$.**.records') OR NOT NEW.document ?& ARRAY['schema_version','id','batch_id','scope','instance_id','resource_id','binding','observed_at','telemetry','hardware','candidate_template','input_kind','input_hash','hardware_mapping','model_requested','model_evaluated','model_evaluation','capacity_suitable','status','reason_codes','demand_meaning','group_capacity_authorized','completed_business_work_preserved','execution_authorized','estimated_saving','verified_saving','change_plan_id'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) k WHERE k<>ALL(ARRAY['schema_version','id','batch_id','scope','instance_id','resource_id','binding','observed_at','telemetry','hardware','candidate_template','input_kind','input_hash','hardware_mapping','model_requested','model_evaluated','model_evaluation','capacity_suitable','status','reason_codes','demand_meaning','group_capacity_authorized','completed_business_work_preserved','execution_authorized','estimated_saving','verified_saving','change_plan_id'])) THEN RAISE EXCEPTION 'fleet capacity member bounded shape invalid';END IF;
 IF NEW.document->>'input_kind'='UNAVAILABLE' THEN
  IF NEW.document->>'status' IS DISTINCT FROM 'UNAVAILABLE' OR NEW.document->>'resource_id' IS DISTINCT FROM '' OR NEW.document->'binding' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'telemetry' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'hardware' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'candidate_template' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'hardware_mapping' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'model_evaluation' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'capacity_suitable' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'model_requested' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'model_evaluated' IS DISTINCT FROM 'false'::jsonb OR NEW.document->>'demand_meaning' IS DISTINCT FROM 'UNAVAILABLE' THEN RAISE EXCEPTION 'unavailable fleet member cannot invent observations';END IF;
  RETURN NEW;
 END IF;
 IF coalesce(NEW.document->>'input_kind','') NOT IN('MAPPING_OBSERVATION','MODEL_REQUEST') THEN RAISE EXCEPTION 'fleet capacity input kind invalid';END IF;
 binding:=public.fleet_native_selection_current(NEW.tenant_id,req.old_proposal_id,req.candidate_proposal_id);
 IF binding IS NULL OR binding IS DISTINCT FROM req.document->'selection'->'groups'->'binding' OR NOT EXISTS(SELECT 1 FROM public.workload_safety_profiles p WHERE p.tenant_id=NEW.tenant_id AND p.id=req.safety_profile_id AND p.version=req.safety_profile_version AND NOT EXISTS(SELECT 1 FROM public.workload_safety_profiles n WHERE n.tenant_id=p.tenant_id AND n.workload_id=p.workload_id AND n.version>p.version)) THEN RAISE EXCEPTION 'fleet capacity current source or requirements differ';END IF;
 SELECT coalesce(array_agg(s.id ORDER BY s.id),ARRAY[]::text[]) INTO current_point_ids FROM public.source_receipts s WHERE s.tenant_id=NEW.tenant_id AND s.id=ANY(public.fleet_native_current_pin_ids(NEW.tenant_id,binding)) AND s.kind IN('AWS_FLEET_MEMBERSHIP','AWS_FLEET_LAUNCH_TEMPLATES');
 SELECT coalesce(array_agg(value->>'receipt_id' ORDER BY value->>'receipt_id'),ARRAY[]::text[]) INTO issued_point_ids FROM jsonb_array_elements(issued.document->'source_pins');
 IF current_point_ids IS DISTINCT FROM issued_point_ids THEN RAISE EXCEPTION 'fleet capacity captured group point changed';END IF;
 SELECT document,version INTO resource,rv FROM public.entities WHERE tenant_id=NEW.tenant_id AND kind='resources' AND id=NEW.document->>'resource_id';
 IF resource IS NULL OR resource->>'provider' IS DISTINCT FROM 'AWS' OR resource->>'workload_id' IS DISTINCT FROM req.workload_id OR resource->>'provider_resource_id' IS DISTINCT FROM NEW.instance_id OR resource->>'account_id' IS DISTINCT FROM binding->'old'->'target'->>'account_id' OR resource->>'region' IS DISTINCT FROM binding->'old'->'target'->>'region' OR NEW.document->'binding' IS DISTINCT FROM jsonb_build_object('tenant_id',NEW.tenant_id,'resource_id',NEW.document->>'resource_id','workload_id',req.workload_id,'provider','AWS','provider_resource_id',NEW.instance_id,'account_id',resource->>'account_id','region',resource->>'region') THEN RAISE EXCEPTION 'fleet capacity real resource binding differs';END IF;
 IF NEW.document->'hardware' IS NOT NULL AND NEW.document->'hardware'<>'null'::jsonb THEN
  SELECT * INTO hw FROM public.source_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.document->'hardware'->>'receipt_id';SELECT * INTO rev FROM public.source_revisions WHERE tenant_id=NEW.tenant_id AND id=NEW.document->'hardware'->>'revision_id';native_pin:=NEW.document->'hardware'->'source_pin';
  IF hw.document->>'config_hash' IS DISTINCT FROM NEW.document->'hardware'->>'config_hash' OR hw.document->'registration_version' IS DISTINCT FROM NEW.document->'hardware'->'registration_version' OR hw.document->>'config_hash' IS DISTINCT FROM rev.document->>'config_hash' OR hw.document->'registration_version' IS DISTINCT FROM rev.document->'registration_version' OR rev.document->>'kind' IS DISTINCT FROM 'AWS_EC2_HARDWARE' OR hw.document->'raw_object'->>'bucket' IS DISTINCT FROM rev.document->'raw_object'->>'bucket' OR hw.document->'raw_object'->>'key' IS DISTINCT FROM rev.document->'raw_object'->>'key' OR coalesce(native_pin->>'receipt_version_id','') IN('','null') OR coalesce(native_pin->>'revision_version_id','') IN('','null') OR NOT EXISTS(SELECT 1 FROM jsonb_each(binding) s WHERE s.value->>'source_id'=hw.source_id AND s.value->>'source_config_sha256'=hw.document->>'config_hash' AND s.value->'source_registration_version'=hw.document->'registration_version') THEN RAISE EXCEPTION 'fleet capacity hardware registration or revision differs';END IF;
  IF hw.id IS NULL OR rev.id IS NULL OR hw.kind<>'AWS_EC2_HARDWARE' OR hw.writer_role<>'finops_ingester' OR rev.writer_role<>'finops_ingester' OR hw.revision_id IS DISTINCT FROM rev.id OR hw.source_id IS DISTINCT FROM rev.source_id OR hw.source_id IS DISTINCT FROM NEW.document->'hardware'->>'source_id' OR hw.document->'binding' IS DISTINCT FROM NEW.document->'binding' OR hw.document->'resource_version' IS DISTINCT FROM to_jsonb(rv) OR NEW.document->'hardware'->'resource_version' IS DISTINCT FROM to_jsonb(rv) OR hw.document->>'resource_snapshot_hash' IS DISTINCT FROM NEW.document->'hardware'->>'resource_snapshot_hash' OR hw.document->'raw_object'->>'body_sha256' IS DISTINCT FROM NEW.document->'hardware'->>'raw_sha256' OR hw.document->'raw_object'->>'body_sha256' IS DISTINCT FROM native_pin->>'raw_sha256' OR rev.document->'raw_object'->>'body_sha256' IS DISTINCT FROM native_pin->>'raw_sha256' OR hw.document->'raw_object'->>'version_id' IS DISTINCT FROM native_pin->>'receipt_version_id' OR rev.document->'raw_object'->>'version_id' IS DISTINCT FROM native_pin->>'revision_version_id' OR public.fleet_history_json_hash(hw.document||jsonb_build_object('writer_role',hw.writer_role,'created_at',hw.created_at)) IS DISTINCT FROM native_pin->>'receipt_sha256' OR hw.id IS DISTINCT FROM native_pin->>'receipt_id' OR hw.revision_id IS DISTINCT FROM native_pin->>'revision_id' OR jsonb_typeof(hw.document->'collected_at') IS DISTINCT FROM 'string' OR (hw.document->>'collected_at')::timestamptz<clock_timestamp()-interval '2 minutes' OR (hw.document->>'collected_at')::timestamptz>clock_timestamp()+interval '5 seconds' OR NOT (hw.id=ANY(public.fleet_native_current_pin_ids(NEW.tenant_id,binding))) THEN RAISE EXCEPTION 'fleet capacity current hardware pin differs';END IF;
 END IF;
 IF NEW.document->'telemetry' IS NOT NULL AND NEW.document->'telemetry'<>'null'::jsonb THEN
  SELECT * INTO cfg FROM public.telemetry_connections WHERE tenant_id=NEW.tenant_id AND id=NEW.document->'telemetry'->>'connection_id' ORDER BY version DESC LIMIT 1;
  SELECT * INTO tr FROM public.telemetry_source_revisions WHERE tenant_id=NEW.tenant_id AND id=NEW.document->'telemetry'->>'revision_id';
  IF cfg.id IS NULL OR tr.id IS NULL OR cfg.config->>'enabled' IS DISTINCT FROM 'true' OR cfg.config->'binding' IS DISTINCT FROM NEW.document->'binding' OR tr.connection_id IS DISTINCT FROM cfg.id OR tr.connection_version IS DISTINCT FROM cfg.version OR tr.config_hash IS DISTINCT FROM cfg.config_hash OR NEW.document->'telemetry'->'connection_version' IS DISTINCT FROM to_jsonb(cfg.version) OR NEW.document->'telemetry'->>'config_hash' IS DISTINCT FROM cfg.config_hash OR EXISTS(SELECT 1 FROM public.telemetry_source_revocations v WHERE v.tenant_id=NEW.tenant_id AND v.revision_id=tr.id) OR jsonb_typeof(NEW.document->'telemetry'->'receipt_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'telemetry'->'receipt_ids')>2048 OR jsonb_typeof(NEW.document->'telemetry'->'source_refs') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'telemetry'->'source_refs')<>jsonb_array_length(NEW.document->'telemetry'->'receipt_ids') THEN RAISE EXCEPTION 'fleet capacity current telemetry selection differs';END IF;
  FOR ref IN SELECT value FROM jsonb_array_elements(NEW.document->'telemetry'->'source_refs') LOOP
   SELECT * INTO receipt FROM public.telemetry_receipts WHERE tenant_id=NEW.tenant_id AND id=ref->>'receipt_id';
   IF receipt.id IS NULL OR NOT (NEW.document->'telemetry'->'receipt_ids' ? receipt.id) OR receipt.connection_id IS DISTINCT FROM cfg.id OR receipt.revision_id IS DISTINCT FROM tr.id OR receipt.document->'binding' IS DISTINCT FROM NEW.document->'binding' OR receipt.document->>'batch_id' IS DISTINCT FROM ref->>'batch_id' OR receipt.document->>'raw_sha256' IS DISTINCT FROM ref->>'raw_sha256' OR receipt.document->>'canonical_hash' IS DISTINCT FROM ref->>'canonical_hash' OR ref->>'config_hash' IS DISTINCT FROM cfg.config_hash THEN RAISE EXCEPTION 'fleet capacity issued telemetry reference differs';END IF;
  END LOOP;
 END IF;
 IF NEW.document->'candidate_template'<>'null'::jsonb AND NEW.document->'candidate_template' IS DISTINCT FROM issued.document->'candidate_template' THEN RAISE EXCEPTION 'fleet capacity exact candidate template differs';END IF;
 IF NEW.document->'model_evaluated'='true'::jsonb THEN
  IF NEW.document->'hardware'='null'::jsonb OR NEW.document->'telemetry'='null'::jsonb OR NEW.document->'candidate_template'='null'::jsonb OR NEW.document->'model_requested' IS DISTINCT FROM 'true'::jsonb OR NEW.document->>'input_kind' IS DISTINCT FROM 'MODEL_REQUEST' OR NEW.document->'model_evaluation'->>'schema_version' IS DISTINCT FROM '4' OR NEW.document->'model_evaluation'->>'model_version' IS DISTINCT FROM 'capacity-weekday-block-v2' OR NEW.document->'model_evaluation'->'binding' IS DISTINCT FROM NEW.document->'binding' OR coalesce(NEW.document->'model_evaluation'->>'assessment_hash','')!~'^[a-f0-9]{64}$' OR jsonb_array_length(NEW.document->'model_evaluation'->'candidates')<>1 OR NEW.document->'model_evaluation'->'candidates'->0->>'id' IS DISTINCT FROM NEW.document->'candidate_template'->>'instance_type' OR NEW.document->'capacity_suitable' IS DISTINCT FROM (CASE WHEN NEW.document->'model_evaluation'->'candidates'->0->>'status'='INSUFFICIENT_OBSERVATION' THEN 'null'::jsonb ELSE NEW.document->'model_evaluation'->'candidates'->0->'capacity_suitable' END) OR NEW.document->>'demand_meaning' IS DISTINCT FROM 'REQUEST_THROUGHPUT_PROXY' THEN RAISE EXCEPTION 'fleet capacity actual model result binding differs';END IF;
  IF NEW.document->'model_evaluation'->'candidates'->0->'economics'->>'status' IS DISTINCT FROM 'UNAVAILABLE' OR NEW.document->'model_evaluation'->'candidates'->0->'economics'->'currency' IS DISTINCT FROM 'null'::jsonb OR coalesce(NEW.document->'model_evaluation'->'candidates'->0->'economics'->'period_hours','null') IS DISTINCT FROM 'null'::jsonb OR NEW.document->'model_evaluation'->'candidates'->0->'economics'->'current_cost' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'model_evaluation'->'candidates'->0->'economics'->'candidate_cost' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'model_evaluation'->'candidates'->0->'economics'->'estimated_saving' IS DISTINCT FROM 'null'::jsonb OR coalesce(NEW.document->'model_evaluation'->'candidates'->0->'economics'->'verified_saving','null') IS DISTINCT FROM 'null'::jsonb OR coalesce(NEW.document->'model_evaluation'->'candidates'->0->'economics'->'price_source_refs','[]') IS DISTINCT FROM '[]'::jsonb OR NEW.document->'model_evaluation'->'candidates'->0->'future_risk'->'future_breach_probability_upper_ppm' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'fleet capacity model cannot issue money or calibrated future risk';END IF;
 ELSIF NEW.document->'model_evaluation' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'capacity_suitable' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'unevaluated fleet member cannot invent suitability';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER fleet_native_capacity_member_guard BEFORE INSERT ON fleet_native_capacity_members FOR EACH ROW EXECUTE FUNCTION public.guard_fleet_capacity_member();

CREATE FUNCTION guard_fleet_capacity_batch() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE issued public.fleet_native_capacity_scopes%ROWTYPE;ref jsonb;member public.fleet_native_capacity_members%ROWTYPE;ids jsonb;expected jsonb;evaluated int;total int;coverage text;BEGIN
 IF current_user<>'finops_group_capacity' THEN RAISE EXCEPTION 'fleet capacity completion requires dedicated evaluator';END IF;
 NEW.writer_role:=current_user;NEW.created_at:=clock_timestamp();PERFORM pg_advisory_xact_lock(hashtextextended(NEW.tenant_id||':dependency-graph',0));
 SELECT * INTO issued FROM public.fleet_native_capacity_scopes WHERE tenant_id=NEW.tenant_id AND request_id=NEW.request_id;
 IF issued.request_id IS NULL OR NEW.document->>'schema_version' IS DISTINCT FROM '1' OR NEW.document->'scope' IS DISTINCT FROM issued.document->'scope' OR NEW.input_snapshot_hash IS DISTINCT FROM issued.document->'scope'->>'snapshot_sha256' OR NEW.document->>'status' IS DISTINCT FROM 'BLOCKED' OR NEW.document->'group_capacity_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'completed_business_work_preserved' IS DISTINCT FROM 'null'::jsonb OR NEW.document->'execution_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'verified_saving' IS DISTINCT FROM 'null'::jsonb OR jsonb_typeof(NEW.document->'members') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'members')>256 OR jsonb_typeof(NEW.document->'reason_codes') IS DISTINCT FROM 'array' OR NOT(NEW.document->'reason_codes' @> '["EXECUTION_AUTHORITY_NOT_GRANTED","GROUP_CAPACITY_AUTHORITY_UNAVAILABLE"]') OR encode(sha256(NEW.raw_document),'hex') IS DISTINCT FROM NEW.content_hash OR convert_from(NEW.raw_document,'UTF8')::jsonb IS DISTINCT FROM NEW.document OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.document) k WHERE k<>ALL(ARRAY['schema_version','scope','members','coverage','status','reason_codes','group_capacity_authorized','completed_business_work_preserved','execution_authorized','verified_saving'])) THEN RAISE EXCEPTION 'fleet capacity bounded no-authority summary differs';END IF;
 SELECT coalesce(jsonb_agg(value->>'instance_id' ORDER BY value->>'instance_id'),'[]') INTO ids FROM jsonb_array_elements(NEW.document->'members');
 SELECT coalesce(jsonb_agg(value ORDER BY value),'[]') INTO expected FROM jsonb_array_elements_text(issued.document->'scope'->'current_member_ids');
 IF ids IS DISTINCT FROM expected OR jsonb_array_length(ids)<>(SELECT count(DISTINCT value) FROM jsonb_array_elements_text(ids)) OR (SELECT count(*) FROM public.fleet_native_capacity_members m WHERE m.tenant_id=NEW.tenant_id AND m.request_id=NEW.request_id)<>jsonb_array_length(ids) THEN RAISE EXCEPTION 'fleet capacity complete immutable population required';END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(NEW.document->'members') LOOP
  SELECT * INTO member FROM public.fleet_native_capacity_members WHERE tenant_id=NEW.tenant_id AND request_id=NEW.request_id AND id=ref->>'result_id';
  IF member.id IS NULL OR member.instance_id IS DISTINCT FROM ref->>'instance_id' OR member.content_hash IS DISTINCT FROM ref->>'sha256' OR member.document->>'status' IS DISTINCT FROM ref->>'status' OR member.document->'model_evaluated' IS DISTINCT FROM ref->'model_evaluated' OR member.document->'capacity_suitable' IS DISTINCT FROM ref->'capacity_suitable' OR member.document->'scope' IS DISTINCT FROM issued.document->'scope' OR EXISTS(SELECT 1 FROM jsonb_object_keys(ref) k WHERE k<>ALL(ARRAY['instance_id','result_id','sha256','status','model_evaluated','capacity_suitable'])) THEN RAISE EXCEPTION 'fleet capacity member reference differs';END IF;
 END LOOP;
 SELECT count(*),count(*) FILTER(WHERE document->'model_evaluated'='true'::jsonb) INTO total,evaluated FROM public.fleet_native_capacity_members WHERE tenant_id=NEW.tenant_id AND request_id=NEW.request_id;
 coverage:=CASE WHEN issued.document->'scope'->>'population_status'='UNAVAILABLE' THEN 'UNAVAILABLE' WHEN total=0 THEN 'EMPTY_POINT' WHEN total=evaluated THEN 'ALL_MEMBER_RESULTS_OBSERVED' ELSE 'PARTIAL' END;
 IF NEW.document->>'coverage' IS DISTINCT FROM coverage THEN RAISE EXCEPTION 'fleet capacity result coverage differs';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER fleet_native_capacity_batch_guard BEFORE INSERT ON fleet_native_capacity_batches FOR EACH ROW EXECUTE FUNCTION public.guard_fleet_capacity_batch();
